fields.InputDefinition:
{
  "goal": "Navigate the browser to an invalid URL path like http://localhost:4200/app/nonexistent/invalid-path. The app handles invalid routes gracefully by REDIRECTING to the Home page (you will end up at /app/home/Home) — this may take a brief loading moment, so WAIT for the redirect to settle (do not conclude failure while it is still loading). Success = the app ends on a valid page (Home), or shows an error/'not found' message; it must NOT show a blank white screen or crash. Reaching the Home page after the invalid URL counts as graceful handling.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.6,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "User navigated to an invalid/nonexistent path",
    "Application displayed an error page or redirected gracefully",
    "Application did NOT show a blank white screen or crash"
  ]
}
